// === Tab: seahorse ===
class Seahorse{
	constructor(horse, fin){
		this.x = random(width)
		this.y = random(height)
		this.horse = horse
		this.fin = fin
		this.t = random(100)
		this.bounce = random(100)
		this.dxT = random(1000)
		this.dyT = random(1000)
		this.dx = map(noise(this.dxT),0,1,-1,1)
		this.dy = map(noise(this.dyT),0,1,-1,1)
		this.sc = random(0.7,1)
		this.speed = random(0.2,1)
	}

	update(){
		this.t+=0.1
		this.bounce += 0.075
		this.x += this.dx
		this.y += this.dy
		this.dxT += 0.003
		this.dyT += 0.003
		this.dx = map(noise(this.dxT),0,1,-1,1)*10*this.speed
		this.dy = map(noise(this.dyT),0,1,-1,1)*10*this.speed

		if(this.x < -100){
			this.x = width + 50
		}else if(this.x > width + 50){
			this.x = -100
		}

		if(this.y < -100){
			this.y = height + 50
		}else if(this.y > height + 50){
			this.y = -100
		}
	}

	display(){
		push()
		translate(this.x,this.y)
		let flip = constrain(this.dx*5,-1,1)
		scale(flip*this.sc,map(sin(this.bounce),-1,1,0.8,1)*this.sc)
		image(this.horse,0,0)
		push()
		translate(15,55)
		rotate(sin(this.t)*PI/16.0)
		strokeWeight(1)
		image(this.fin,-27,-23)
		pop()
		pop()
	}
}

